def test_burst(TokenBucket):
    current_time = [0.0]
    bucket = TokenBucket(5, 1.0, lambda: current_time[0])

    for request_number in range(1, 6):
        assert bucket.allow() is True, (
            f"request {request_number} at t=0 should succeed"
        )

    assert bucket.allow() is False, (
        "the sixth request at t=0 should be rejected"
    )

    current_time[0] = 1.0
    assert bucket.allow() is True, (
        "one request should succeed after 1 second of recovery"
    )

